import {
  OPEN_SIDE_PANEL_MESSAGE,
  AGENT_RUNNING_STATE_MESSAGE,
  type OpenSidePanelMessage,
  type AgentRunningStateMessage
} from "../lib/side-panel-bridge"
import { t, initLocaleFromStorage } from "../lib/i18n"

export const FLOATING_BUTTON_ID = "lumino-floating-button"

// content script 启动时恢复 locale（异步，不阻塞按钮创建；默认 en 兜底）
void initLocaleFromStorage()

function requestOpenSidePanel() {
  if (typeof chrome === "undefined" || !chrome.runtime?.sendMessage) {
    return
  }

  const message: OpenSidePanelMessage = {
    type: OPEN_SIDE_PANEL_MESSAGE
  }

  chrome.runtime.sendMessage(message).catch((err) => {
    // Service Worker may be idle/restarting — silently ignore context invalidation
    const msg = err?.message ?? String(err)
    if (!msg.includes("Extension context invalidated") &&
        !msg.includes("Could not establish connection") &&
        !msg.includes("message port closed")) {
      console.warn("[Lumino] sendMessage failed:", msg)
    }
  })
}




/** 默认右边距（侧边栏关闭时） */
const DEFAULT_RIGHT_PX = 24
/** 侧边栏打开时右边距 = 侧边栏宽度 + 间距 */
const SIDEPANEL_WIDTH_PX = 400
const SIDEPANEL_GAP_PX = 16

/**
 * 全页面窗口宽度（不含 Side Panel）。
 * 存储为变量，在 ResizeObserver 中更新，供 enableDrag 使用。
 */
let fullWindowWidth = window.innerWidth

/** 侧边栏是否打开 */
let isSidepanelOpen = false

/**
 * 监听 viewport 宽度变化判断侧边栏开关，
 * 并驱动按钮 right 值。
 */
function setupSidepanelDetector(button: HTMLButtonElement) {
  // 用 window.innerWidth 作为全窗口宽度基线
  fullWindowWidth = window.innerWidth

  const reposition = (open: boolean) => {
    // 去掉拖拽产生的 left/top inline 样式，恢复 right/bottom 定位
    button.style.left = ""
    button.style.top = ""
    button.style.bottom = "24px"

    if (open) {
      button.style.right = (SIDEPANEL_WIDTH_PX + SIDEPANEL_GAP_PX) + "px"
    } else {
      button.style.right = DEFAULT_RIGHT_PX + "px"
    }
  }

  let lastViewportWidth = document.documentElement.clientWidth

  const check = () => {
    const viewportWidth = document.documentElement.clientWidth

    // 对比全窗口宽度和可视宽度判断侧边栏是否打开
    const estimatedOpen = (fullWindowWidth - viewportWidth) > 80
    if (estimatedOpen !== isSidepanelOpen) {
      isSidepanelOpen = estimatedOpen
      reposition(estimatedOpen)
    }

    // 侧边栏关闭时更新全窗口宽度
    if (!estimatedOpen && viewportWidth > fullWindowWidth) {
      fullWindowWidth = viewportWidth
    }

    lastViewportWidth = viewportWidth
  }

  // 初始检测（页面加载时侧边栏可能已打开）
  check()

  if (typeof ResizeObserver !== "undefined") {
    const ro = new ResizeObserver(() => check())
    ro.observe(document.documentElement)
  }

  // window resize 时更新全窗口宽度基线
  window.addEventListener("resize", () => {
    if (!isSidepanelOpen) {
      fullWindowWidth = window.innerWidth
    }
    check()
  })

  // 每 2 秒兜底轮询
  setInterval(check, 2000)
}

const CAT_ICON_URL = "data:image/gif;base64,"

export function createFloatingButton(ownerDocument: Document) {
  const button = ownerDocument.createElement("button")
  const glyph = ownerDocument.createElement("span")

  button.id = FLOATING_BUTTON_ID
  button.type = "button"
  button.className = "lumino-fab"
  button.setAttribute("aria-label", t("floatButton.ariaLabel"))

  const img = ownerDocument.createElement("img")
  img.className = "lumino-fab__img"
  img.src = CAT_ICON_URL
  img.alt = "Lumino"
  img.setAttribute("aria-hidden", "true")

  button.append(img)

  return button
}

function savePosition(x: number, y: number) {
  try {
    localStorage.setItem("lumino-fab-pos", JSON.stringify({ x, y }))
  } catch { /* ignore */ }
}

function loadPosition(): { x: number; y: number } | null {
  try {
    const raw = localStorage.getItem("lumino-fab-pos")
    if (raw) return JSON.parse(raw) as { x: number; y: number }
  } catch { /* ignore */ }
  return null
}

function enableDrag(button: HTMLButtonElement) {
  let dragging = false
  let startX = 0
  let startY = 0
  let startLeft = 0
  let startTop = 0
  let moved = false

  const onStart = (clientX: number, clientY: number) => {
    dragging = true
    moved = false
    startX = clientX
    startY = clientY
    const rect = button.getBoundingClientRect()
    startLeft = rect.left
    startTop = rect.top
    button.style.transition = "none"
  }

  const onMove = (clientX: number, clientY: number) => {
    if (!dragging) return
    const dx = clientX - startX
    const dy = clientY - startY
    if (Math.abs(dx) > 3 || Math.abs(dy) > 3) moved = true
    // 使用全窗口宽度（不含 Side Panel 占用的空间）
    const maxX = fullWindowWidth - button.offsetWidth - 8
    const maxY = window.innerHeight - button.offsetHeight - 8
    const newLeft = Math.min(maxX, Math.max(8, startLeft + dx))
    const newTop = Math.min(maxY, Math.max(8, startTop + dy))
    button.style.left = newLeft + "px"
    button.style.top = newTop + "px"
    button.style.right = "auto"
    button.style.bottom = "auto"
  }

  const onEnd = () => {
    if (!dragging) return
    dragging = false
    button.style.transition = ""
    if (moved) {
      const rect = button.getBoundingClientRect()
      savePosition(rect.left, rect.top)
    }
  }

  button.addEventListener("mousedown", (e) => {
    if (e.button !== 0) return
    e.preventDefault()
    onStart(e.clientX, e.clientY)
  })

  button.addEventListener("touchstart", (e) => {
    if (e.touches.length !== 1) return
    const t = e.touches[0]
    onStart(t.clientX, t.clientY)
  }, { passive: true })

  document.addEventListener("mousemove", (e) => {
    onMove(e.clientX, e.clientY)
  })

  document.addEventListener("touchmove", (e) => {
    if (e.touches.length !== 1) return
    const t = e.touches[0]
    onMove(t.clientX, t.clientY)
  }, { passive: true })

  document.addEventListener("mouseup", onEnd)
  document.addEventListener("touchend", onEnd)

  // Prevent click when dragged
  button.addEventListener("click", (e) => {
    if (moved) {
      e.stopPropagation()
      e.preventDefault()
    }
  }, true)

  // Restore saved position
  const saved = loadPosition()
  if (saved) {
    const maxX = fullWindowWidth - 56 - 8
    const maxY = window.innerHeight - 56 - 8
    button.style.left = Math.min(maxX, Math.max(8, saved.x)) + "px"
    button.style.top = Math.min(maxY, Math.max(8, saved.y)) + "px"
    button.style.right = "auto"
    button.style.bottom = "auto"
  }
}

export function mountFloatingButton(ownerDocument: Document = document) {
  const existingButton = ownerDocument.getElementById(FLOATING_BUTTON_ID)

  if (existingButton instanceof HTMLButtonElement) {
    return existingButton
  }

  const button = createFloatingButton(ownerDocument)
  button.addEventListener("click", requestOpenSidePanel)

  // 监听 agent 运行状态，切换呼吸蒙版动画
  chrome.runtime.onMessage.addListener((message) => {
    if (
      message &&
      typeof message === "object" &&
      (message as AgentRunningStateMessage).type === AGENT_RUNNING_STATE_MESSAGE
    ) {
      const payload = (message as AgentRunningStateMessage).payload
      if (payload.running) {
        button.classList.add("lumino-fab--pulsing")
      } else {
        button.classList.remove("lumino-fab--pulsing")
      }
    }
  })

  ownerDocument.body.append(button)

  // 读取当前主题并设置 data-theme
  chrome.storage.sync.get("theme", (data) => {
    const theme = data.theme || "paper"
    button.setAttribute("data-theme", theme)
  })

  // 监听主题变化
  chrome.storage.onChanged.addListener((changes, areaName) => {
    if (areaName === "sync" && "theme" in changes) {
      const theme = changes.theme.newValue || "paper"
      button.setAttribute("data-theme", theme)
    }
  })

  setupSidepanelDetector(button)
  enableDrag(button)

  return button
}
